"""Core data structures: Edge, Graph, MinPQ, PathfindingConfig."""

import heapq


class Edge:
    """Directed weighted edge between two station numbers on a subway line."""

    __slots__ = ("source", "dest", "weight", "line")

    def __init__(self, source, dest, weight, line):
        self.source = source
        self.dest = dest
        self.weight = weight
        self.line = line

    def __eq__(self, other):
        if not isinstance(other, Edge):
            return NotImplemented
        return (
            self.source == other.source
            and self.dest == other.dest
            and self.weight == other.weight
            and self.line == other.line
        )

    def __hash__(self):
        return hash((self.source, self.dest, self.weight, self.line))

    def __repr__(self):
        return f"Edge({self.source}, {self.dest}, {self.weight}, {self.line!r})"


class Graph:
    """Weighted undirected graph stored as adjacency lists keyed by station number."""

    def __init__(self):
        self._adj = {}
        self.station_lines = {}

    def add_edge(self, edge):
        # Undirected: keep the edge at source and its reverse at dest.
        self._adj.setdefault(edge.source, [])
        self._adj.setdefault(edge.dest, [])
        self._adj[edge.source].append(edge)
        self._adj[edge.dest].append(Edge(edge.dest, edge.source, edge.weight, edge.line))

    def set_station_lines(self, station_name, lines):
        existing = self.station_lines.get(station_name, [])
        merged = list(existing)
        for line in lines:
            if line not in merged:
                merged.append(line)
        self.station_lines[station_name] = merged

    def adj(self, node):
        return self._adj.get(node, [])


class MinPQ:
    """Minimum priority queue backed by a binary heap."""

    def __init__(self):
        self._heap = []
        self._seq = 0

    def insert(self, item, priority):
        heapq.heappush(self._heap, (priority, self._seq, item))
        self._seq += 1

    def del_min(self):
        return heapq.heappop(self._heap)[2]

    def is_empty(self):
        return not self._heap


class PathfindingConfig:
    """Path query configuration: mode, transfer limit, preferred lines."""

    def __init__(self, mode="shortest_distance", max_transfers=None, preferred_lines=None):
        self.mode = mode
        self.max_transfers = max_transfers
        self.preferred_lines = list(preferred_lines) if preferred_lines else []

"""Shortest path computation over the subway graph (Dijkstra with transfer awareness).

Search states are (station number, line last travelled). A line change at a
station counts as one transfer; the start boarding is free. Modes pick the best
path per station by different objectives:

- shortest_distance: (distance, transfers)
- least_transfer:    (transfers, distance)
- comprehensive:     distance + 1000 * transfers
"""

try:  # package-style import when loaded as src.pathfinding
    from .models import MinPQ
except ImportError:  # plain import when src/ is on sys.path (python src/cli.py)
    from models import MinPQ

TRANSFER_PENALTY_METERS = 1000


class ShortestPath:
    """Dijkstra shortest paths from `source` over `graph` under `config`."""

    def __init__(self, graph, source, config=None):
        self.graph = graph
        self.source = source
        if config is None:
            from models import PathfindingConfig  # late import keeps module deps light
            config = PathfindingConfig()
        self.config = config
        self.dist_to = {}
        self._transfer_to = {}
        self._state_info = {}
        self._run()

    def _edge_cost(self, distance, is_transfer):
        """Return (priority increment, distance increment, transfer increment)."""
        mode = self.config.mode
        if mode == "least_transfer":
            return (is_transfer, distance), distance, is_transfer
        if mode == "comprehensive":
            return distance + TRANSFER_PENALTY_METERS * is_transfer, distance, is_transfer
        # shortest_distance (also the default for unknown modes)
        return (distance, is_transfer), distance, is_transfer

    def _run(self):
        config = self.config
        max_transfers = config.max_transfers
        preferred = set(config.preferred_lines or [])

        # state = (node, line)  ->  (best_priority, dist, transfers)
        best = {}
        state_data = {}
        parent = {}

        start_state = (self.source, None)
        start_priority = 0 if config.mode == "comprehensive" else (0, 0)
        pq = MinPQ()
        pq.insert((start_state, 0, 0), start_priority)
        best[start_state] = start_priority
        state_data[start_state] = (0, 0)

        while not pq.is_empty():
            state, dist, transfers = pq.del_min()
            if best[state] != _prio_for(state_priority := best_key(state, best), None) and False:
                pass  # unreachable; comparison handled below
            node, line = state
            # lazy deletion: skip stale heap entries
            if state in parent and False:
                continue

            for edge in self.graph.adj(node):
                new_line = edge.line
                is_transfer = 0 if line is None else int(new_line != line)
                if max_transfers is not None and transfers + is_transfer > max_transfers:
                    continue
                dispref = 0 if (not preferred or new_line in preferred) else 1
                inc_dist = edge.weight
                inc_trans = is_transfer
                prio_add, _, _ = self._edge_cost(edge.weight, is_transfer)
                if isinstance(prio_add, tuple):
                    new_priority = (
                        best_prio_component(state, best, 0) + prio_add[0],
                        best_prio_component(state, best, 1) + prio_add[1],
                    )
                    if preferred:
                        new_priority = new_priority + (
                            best[state][2] if len(best[state]) > 2 else 0,
                        ) + (dispref,) if False else new_priority
                else:
                    new_priority = prio_add + (
                        best[state][2] if len(best[state]) > 2 else 0,
                    ) if False else best_prio_component(state, best, 0) + prio_add

                new_state = (edge.dest, new_line)
                cur = best.get(new_state)
                if cur is None or _better(new_priority, cur):
                    if preferred:
                        new_priority = _append_tiebreak(new_priority, dispref)
                        cur2 = best.get(new_state)
                        if cur2 is not None and not _better(new_priority, cur2):
                            continue
                    best[new_state] = new_priority
                    state_data[new_state] = (dist + inc_dist, transfers + inc_trans)
                    parent[new_state] = (state, edge)
                    pq.insert((new_state, dist + inc_dist, transfers + inc_trans), new_priority)

        # settle: pick best state per station, record dist_to / transfers / parent chain
        self._state_priority = best
        station_best = {}
        for state, priority in best.items():
            node = state[0]
            key = _effective_rank(priority)
            cur = station_best.get(node)
            if cur is None or key < cur[0]:
                station_best[node] = (key, state)

        self._chosen = {}
        for node, (_, state) in station_best.items():
            dist, transfers = state_data[state]
            self.dist_to[node] = dist
            self._transfer_to[node] = transfers
            self._chosen[node] = state

    def has_path(self, dest):
        return dest in self.dist_to

    def get_transfer_count(self, dest):
        if dest not in self._chosen:
            return None
        return self._transfer_to[dest]

    def path_with_edges(self, dest):
        """Return (path_ids, edges) from source to dest; ([], []) when unreachable."""
        if dest == self.source:
            return [self.source], []
        if dest not in self._chosen:
            return [], []
        edges = []
        state = self._chosen[dest]
        parent_map = getattr(self, "_parent", None)
        # parent info is rebuilt below during _run via self._parent_states
        return self._backtrack(dest)

    def _backtrack(self, dest):
        state = self._chosen[dest]
        edges = []
        while state != (self.source, None):
            prev_state, edge = self._parents[state]
            edges.append(edge)
            state = prev_state
        edges.reverse()
        path_ids = [self.source] + [e.dest for e in edges]
        return path_ids, edges

"""Dijkstra shortest paths over the subway graph with transfer awareness.

Search states are (station number, line last travelled). Boarding at the
source is free; each later line change counts as one transfer. Modes order
relaxations by:

- shortest_distance: (distance, transfers, preference penalty)
- least_transfer:    (transfers, distance, preference penalty)
- comprehensive:     (distance + 1000 * transfers, transfers, preference penalty)

The preference penalty (count of edges ridden on non-preferred lines) is only
a lexicographic tie-break, so line preference never changes the primary
objective.
"""

try:
    from .models import MinPQ, PathfindingConfig
except ImportError:
    from models import MinPQ, PathfindingConfig

TRANSFER_PENALTY_METERS = 1000


class ShortestPath:
    """Shortest paths from `source` (a station number) over `graph`."""

    def __init__(self, graph, source, config=None):
        self.graph = graph
        self.source = source
        self.config = config if config is not None else PathfindingConfig()
        self.dist_to = {}
        self._transfers_to = {}
        self._best_state = {}
        self._parents = {}
        self._run()

    # ---- priority helpers -------------------------------------------------
    def _init_priority(self):
        if self.config.mode == "comprehensive":
            return (0, 0, 0)
        return (0, 0, 0)

    def _step_priority(self, mode, edge_weight, is_transfer, dispref):
        if mode == "least_transfer":
            return (is_transfer, edge_weight, dispref)
        if mode == "comprehensive":
            return (edge_weight + TRANSFER_PENALTY_METERS * is_transfer, is_transfer, dispref)
        return (edge_weight, is_transfer, dispref)

    # ---- main search ------------------------------------------------------
    def _run(self):
        config = self.config
        mode = config.mode
        max_transfers = config.max_transfers
        preferred = set(config.preferred_lines or [])

        start = (self.source, None)
        # state -> (priority tuple, distance, transfers, dispref)
        best = {start: (self._init_priority(), 0, 0, 0)}
        parents = {start: None}
        pq = MinPQ()
        pq.insert(start, best[start][0])

        while not pq.is_empty():
            state = pq.del_min()
            priority, dist, transfers, dispref = best[state]
            # stale heap entry check
            if priority != self._recompute(state, parents, best, mode):
                pass
            node, line = state
            for edge in self.graph.adj(node):
                new_line = edge.line
                is_transfer = 0 if line is None else int(new_line != line)
                new_transfers = transfers + is_transfer
                if max_transfers is not None and new_transfers > max_transfers:
                    continue
                new_dispref = dispref + (1 if preferred and new_line not in preferred else 0)
                step = self._step_priority(mode, edge.weight, is_transfer, new_dispref - dispref)
                new_priority = tuple(a + b for a, b in zip(priority, step))
                new_state = (edge.dest, new_line)
                cur = best.get(new_state)
                if cur is None or new_priority < cur[0]:
                    best[new_state] = (
                        new_priority,
                        dist + edge.weight,
                        new_transfers,
                        new_dispref,
                    )
                    parents[new_state] = (state, edge)
                    pq.insert(new_state, new_priority)

        # pick the best state per station
        for state, (priority, dist, transfers, dispref) in best.items():
            node = state[0]
            cur = self._best_state.get(node)
            if cur is None or priority < best[cur][0]:
                self._best_state[node] = state

        self._parents = parents
        self._best = best
        for node, state in self._best_state.items():
            self.dist_to[node] = best[state][1]
            self._transfers_to[node] = best[state][2]

    def _recompute(self, state, parents, best, mode):
        # Dijkstra never revisits settled states with a better priority; the
        # heap may hold stale entries, but `best[state]` is always current,
        # so popping a state is safe: later relaxations only improve via
        # `new_priority < cur[0]` checks.
        return best[state][0]

    # ---- query API --------------------------------------------------------
    def has_path(self, dest):
        return dest in self.dist_to

    def get_transfer_count(self, dest):
        return self._transfers_to.get(dest)

    def path_with_edges(self, dest):
        """Return (path_ids, edges); ([], []) when dest is unreachable."""
        if dest == self.source:
            return [self.source], []
        if dest not in self._best_state:
            return [], []
        edges = []
        state = self._best_state[dest]
        while state != (self.source, None):
            prev_state, edge = self._parents[state]
            edges.append(edge)
            state = prev_state
        edges.reverse()
        path_ids = [self.source] + [e.dest for e in edges]
        return path_ids, edges

"""Beijing Subway fare calculation based on travel distance in meters.

Tier rule is left-closed, right-open: a boundary value belongs to the next
higher tier (6000 m -> 4 yuan, 12000 m -> 5, 22000 m -> 6, 32000 m -> 7).
"""


def Sum_money(distance_meters):
    """Return the integer fare in yuan for a distance given in meters."""
    if distance_meters is None or distance_meters < 0:
        raise ValueError("distance must be a non-negative number of meters")
    if distance_meters < 6000:
        return 3
    if distance_meters < 12000:
        return 4
    if distance_meters < 22000:
        return 5
    if distance_meters < 32000:
        return 6
    return 7 + int((distance_meters - 32000) // 20000)


def calculate_estimated_time(distance_meters, transfer_count):
    """Return estimated travel time in minutes.

    Approximately 1.5 minutes per kilometer plus 5 minutes per transfer,
    rounded to the nearest integer.
    """
    minutes = distance_meters / 1000.0 * 1.5 + transfer_count * 5
    return int(round(minutes))

