"""Command line interface for the Beijing Subway fare calculation system."""

import argparse
import json
import sys

try:
    from . import data_loader
    from .models import Edge, Graph, PathfindingConfig
    from .pathfinding import ShortestPath
    from .fare_calculator import Sum_money, calculate_estimated_time
except ImportError:
    import data_loader
    from models import Edge, Graph, PathfindingConfig
    from pathfinding import ShortestPath
    from fare_calculator import Sum_money, calculate_estimated_time

FORMAT_ERROR = "Input format incorrect, please use 'Starting Station; Ending Station' format"
SAME_STATION_ERROR = "Starting station cannot be the same as the ending station"


def build_network(data):
    """Return (graph, station_to_number, number_to_station) from raw data."""
    station_to_number = {}
    number_to_station = []
    graph = Graph()

    for station in data["stations"]:
        name = station["name"]
        if name not in station_to_number:
            station_to_number[name] = len(number_to_station)
            number_to_station.append(name)
        graph.set_station_lines(name, station.get("lines", []))

    for conn in data["connections"]:
        src = station_to_number.get(conn["source"])
        dst = station_to_number.get(conn["dest"])
        if src is None or dst is None:
            continue
        graph.add_edge(Edge(src, dst, conn["distance"], conn["line"]))

    return graph, station_to_number, number_to_station


def group_path_by_lines(path_ids, edges, number_to_station):
    """Group the path into per-line segments: [(line, [station names]), ...]."""
    segments = []
    if not path_ids:
        return segments
    current_line = edges[0].line if edges else None
    current = [number_to_station[path_ids[0]]]
    for i, edge in enumerate(edges):
        if edge.line != current_line:
            segments.append((current_line, current, True))
            current_line = edge.line
            current = [current[-1]]
        current.append(number_to_station[edge.dest])
    segments.append((current_line, current, False))
    return segments


def format_text_result(start_name, end_name, segments, distance, fare, time_minutes, transfers):
    lines = [
        "--- Path Query Result ---",
        f"Start Station: {start_name}",
        f"End Station: {end_name}",
        "",
        "Detailed Path:",
    ]
    for idx, (line, stations, is_transfer_end) in enumerate(segments):
        suffix = " [Transfer Station]" if is_transfer_end else ""
        lines.append(f"  {line}: {' → '.join(stations)}{suffix}")
    lines.append("")
    lines.append(f"Total Distance: {distance} meters ({distance / 1000:.2f} km)")
    lines.append(f"Estimated Fare: {fare} yuan")
    lines.append(f"Estimated Travel Time: {time_minutes} minutes")
    lines.append(f"Transfer Count: {transfers} {'time' if transfers == 1 else 'times'}")
    return "\n".join(lines)


def build_json_result(start_name, end_name, path_names, distance, fare, time_minutes, transfers, lines_involved):
    return {
        "query": {"start_station": start_name, "end_station": end_name},
        "result": {
            "path": path_names,
            "total_distance": distance,
            "fare": fare,
            "estimated_time": time_minutes,
            "transfer_count": transfers,
            "lines_involved": lines_involved,
        },
    }


def check_data(data):
    """Run the data integrity check and return a report string."""
    problems = []
    names = set()
    for station in data["stations"]:
        name = station.get("name")
        if not name:
            problems.append("Station entry without a name")
            continue
        if name in names:
            problems.append(f"Duplicate station name: {name}")
        names.add(name)
        if not station.get("lines"):
            problems.append(f"Station without line affiliation: {name}")

    for conn in data["connections"]:
        for key in ("source", "dest"):
            if conn.get(key) not in names:
                problems.append(f"Connection references unknown station: {conn.get(key)}")
        distance = conn.get("distance")
        if not isinstance(distance, (int, float)) or distance <= 0:
            problems.append(f"Invalid distance for {conn.get('source')} - {conn.get('dest')}: {distance}")
        if not conn.get("line"):
            problems.append(f"Connection without line: {conn.get('source')} - {conn.get('dest')}")

    covered_lines = {c["line"] for c in data["connections"] if c.get("line")}
    for station in data["stations"]:
        for line in station.get("lines", []):
            if line not in covered_lines:
                problems.append(f"Line not covered by connections: {line}")

    report = ["Data integrity check"]
    if problems:
        report.append(f"Issues found: {len(problems)}")
        report.extend(f"  - {p}" for p in problems)
    else:
        report.append(f"OK: {len(names)} stations, {len(data['connections'])} connections, "
                      f"{len(covered_lines)} lines")
    return "\n".join(report)


def process_query(line, graph, station_to_number, number_to_station, config):
    """Return (output_text, json_payload) for one query line."""
    parts = [p.strip() for p in line.split(";")]
    if len(parts) != 2 or not parts[0] or not parts[1]:
        return FORMAT_ERROR, None
    start_name, end_name = parts
    if start_name == end_name:
        return SAME_STATION_ERROR, None
    src = station_to_number.get(start_name)
    dst = station_to_number.get(end_name)
    if src is None or dst is None:
        missing = start_name if src is None else end_name
        which = "Starting" if src is None else "Ending"
        return f"{which} station '{missing}' does not exist, please check the station name", None

    shortest = ShortestPath(graph, src, config)
    if dst not in shortest.dist_to:
        return "No path found between the two stations", None
    path_ids, edges = shortest.path_with_edges(dst)
    distance = shortest.dist_to[dst]
    transfers = shortest.get_transfer_count(dst)
    try:
        fare = Sum_money(distance)
        time_minutes = calculate_estimated_time(distance, transfers)
    except (ValueError, TypeError) as exc:
        return f"Fare calculation failed: {exc}", None

    segments = group_path_by_lines(path_ids, edges, number_to_station)
    text = format_text_result(start_name, end_name, segments, distance, fare, time_minutes, transfers)
    path_names = [number_to_station[i] for i in path_ids]
    lines_involved = []
    for edge in edges:
        if edge.line not in lines_involved:
            lines_involved.append(edge.line)
    payload = build_json_result(start_name, end_name, path_names, distance, fare,
                                time_minutes, transfers, lines_involved)
    return text, payload


def main(argv=None):
    parser = argparse.ArgumentParser(description="Beijing Subway fare calculation system")
    parser.add_argument("--output_file", help="Export query results to this file")
    parser.add_argument("--format", choices=["text", "json"], default="text")
    parser.add_argument("--mode", choices=["shortest_distance", "least_transfer", "comprehensive"],
                        default="shortest_distance")
    parser.add_argument("--max_transfers", type=int, default=None)
    parser.add_argument("--line_preference", action="append", default=None)
    parser.add_argument("--check_data", action="store_true", help="Run data integrity check and exit")
    args = parser.parse_args(argv)

    data = data_loader.load_subway_data()

    if args.check_data:
        print(check_data(data))
        return 0

    graph, station_to_number, number_to_station = build_network(data)
    config = PathfindingConfig(
        mode=args.mode,
        max_transfers=args.max_transfers,
        preferred_lines=args.line_preference,
    )

    for raw in sys.stdin:
        line = raw.strip()
        if not line:
            continue
        try:
            text, payload = process_query(line, graph, station_to_number, number_to_station, config)
        except Exception as exc:  # path calculation exception handling
            text, payload = f"Path calculation failed: {exc}", None
        print(text)
        if args.output_file and payload is not None:
            try:
                with open(args.output_file, "w", encoding="utf-8") as f:
                    if args.format == "json":
                        json.dump(payload, f, ensure_ascii=False, indent=2)
                    else:
                        f.write(text)
            except OSError as exc:
                print(f"Failed to write output file: {exc}")
        print()
    return 0


if __name__ == "__main__":
    sys.exit(main())

