"""Core data structures: Edge, Graph, MinPQ, PathfindingConfig."""
import heapq


class Edge:
    """Directed edge: station numbers at both ends, weight in meters, line name."""

    def __init__(self, source, dest, weight, line):
        self.source = source
        self.dest = dest
        self.weight = weight
        self.line = line

    def __eq__(self, other):
        if not isinstance(other, Edge):
            return NotImplemented
        return (self.source, self.dest, self.weight, self.line) == (
            other.source, other.dest, other.weight, other.line)

    def __hash__(self):
        return hash((self.source, self.dest, self.weight, self.line))

    def __repr__(self):
        return f"Edge({self.source}, {self.dest}, {self.weight}, {self.line!r})"


class Graph:
    """Weighted graph stored as adjacency lists; add_edge keeps it undirected."""

    def __init__(self):
        self._adj = {}
        self.station_lines = {}

    def add_node(self, node):
        self._adj.setdefault(node, [])

    def add_edge(self, edge):
        self._adj.setdefault(edge.source, []).append(edge)
        self._adj.setdefault(edge.dest, []).append(
            Edge(edge.dest, edge.source, edge.weight, edge.line))

    def set_station_lines(self, station_name, lines):
        self.station_lines[station_name] = list(lines)

    def adj(self, node):
        return self._adj.get(node, [])

    def __len__(self):
        return len(self._adj)


class MinPQ:
    """Minimum priority queue backed by a binary heap."""

    def __init__(self):
        self._heap = []
        self._count = 0

    def insert(self, item, priority):
        heapq.heappush(self._heap, (priority, self._count, item))
        self._count += 1

    def del_min(self):
        return heapq.heappop(self._heap)[2]

    def is_empty(self):
        return not self._heap


