"""Load the Beijing subway network from subway_data.json and build the graph."""
import json
import pathlib

from models import Edge, Graph

DATA_FILE_PATH = pathlib.Path(__file__).resolve().parent.parent / "subway_data.json"


def load_subway_data(path=DATA_FILE_PATH):
    """Read the JSON file at path; return dict with 'stations' and 'connections'."""
    with open(path, "r", encoding="utf-8") as f:
        data = json.load(f)
    return {"stations": data["stations"], "connections": data["connections"]}


def build_network(data):
    """Build graph plus name<->number maps from loaded subway data.

    Returns (graph, station_to_number, number_to_station).
    """
    station_to_number = {}
    number_to_station = []
    graph = Graph()

    for station in data["stations"]:
        name = station["name"]
        if name not in station_to_number:
            station_to_number[name] = len(number_to_station)
            number_to_station.append(name)
        number = station_to_number[name]
        graph.add_node(number)
        graph.set_station_lines(name, station.get("lines", []))

    for conn in data["connections"]:
        src = station_to_number.get(conn["source"])
        dst = station_to_number.get(conn["dest"])
        if src is None or dst is None:
            continue
        graph.add_edge(Edge(src, dst, conn["distance"], conn["line"]))

    return graph, station_to_number, number_to_station


def check_data_integrity(data):
    """Run data integrity checks. Returns (ok: bool, messages: list[str])."""
    messages = []
    stations = data.get("stations", [])
    connections = data.get("connections", [])
    names = {s["name"] for s in stations}

    missing = set()
    for conn in connections:
        for key in ("source", "dest"):
            if conn[key] not in names:
                missing.add(conn[key])
    if missing:
        messages.append("Connections reference unknown stations: "
                        + ", ".join(sorted(missing)))

    covered = set()
    for s in stations:
        for line in s.get("lines", []):
            covered.add(line)
    if not covered:
        messages.append("No line information found in station data")

    bad_dist = [c for c in connections
                if not isinstance(c.get("distance"), (int, float)) or c["distance"] <= 0]
    if bad_dist:
        messages.append(f"{len(bad_dist)} connection(s) have invalid distance")

    if not connections:
        messages.append("No connections defined")

    if not missing and not bad_dist and covered and connections:
        messages.append("OK")
        return True, messages
    return False, messages

"""Shortest path search (Dijkstra with priority queue) over the subway graph.

States are (station, current_line) so that transfers (line changes) can be
counted and limited. Three modes:
  - shortest_distance: minimize total distance
  - least_transfer:    minimize number of transfers
  - comprehensive:     minimize distance + 1000m penalty per transfer
"""

from models import MinPQ

TRANSFER_PENALTY = 1000  # meters, for comprehensive mode
NO_LINE = None


class ShortestPath:
    def __init__(self, graph, source, config=None):
        self.graph = graph
        self.source = source
        self.config = config
        mode = "shortest_distance"
        max_transfers = None
        preferred = set()
        if config is not None:
            mode = getattr(config, "mode", "shortest_distance") or "shortest_distance"
            max_transfers = getattr(config, "max_transfers", None)
            preferred = set(getattr(config, "preferred_lines", None) or [])
        self.mode = mode
        self.max_transfers = max_transfers
        self.preferred = preferred

        self.dist_to = {}
        self._transfer_count = {}
        self._edge_to = {}       # state -> Edge used to enter this state
        self._prev_state = {}    # state -> previous state
        self._run()

    def _state_key(self, node, line):
        return (node, line if line is not NO_LINE else "")

    def _priority(self, dist, transfers, node, line):
        """Sort key: primary metric by mode, then transfers, then distance.

        Preferred-line edges rank first among equal keys (tie-break only).
        """
        if self.mode == "least_transfer":
            primary = transfers
        elif self.mode == "comprehensive":
            primary = dist + TRANSFER_PENALTY * transfers
        else:
            primary = dist
        pref = 0 if (line and line in self.preferred) else 1
        return (primary, pref, transfers, dist)

    def _run(self):
        pq = MinPQ()
        start = self._state_key(self.source, NO_LINE)
        best = {start: (0, 0)}  # state -> (dist, transfers)
        pq.insert((start, NO_LINE), self._priority(0, 0, self.source, None))

        while not pq.is_empty():
            (state, in_line) = pq.del_min()
            node = state[0]
            dist, transfers = best[state]
            # stale entry check
            if self._priority(dist, transfers, node, in_line) != (
                    self._priority(*best.get(state, (float("inf"), float("inf"))),
                                   node, in_line)):
                continue
            for edge in self.graph.adj(node):
                nline = edge.line
                if edge.line == in_line:
                    ntrans = transfers
                elif in_line is NO_LINE:
                    ntrans = 0
                else:
                    ntrans = transfers + 1
                if self.max_transfers is not None and ntrans > self.max_transfers:
                    continue
                ndist = dist + edge.weight
                nstate = self._state_key(edge.dest, nline)
                cur = best.get(nstate)
                if cur is None or ndist < cur[0]:
                    best[nstate] = (ndist, ntrans)
                    self._edge_to[nstate] = edge
                    self._prev_state[nstate] = state
                    pq.insert((nstate, nline),
                              self._priority(ndist, ntrans, edge.dest, nline))

        # Aggregate per station: pick the best state by mode priority.
        self._best_state = {}
        for (node, line), (dist, transfers) in best.items():
            if node == self.source:
                self._set_result(node, 0, 0, None)
                continue
            cur = self._best_state.get(node)
            if cur is None:
                self._best_state[node] = ((node, line), dist, transfers)
                continue
            old_key = self._priority(cur[2], cur[3], node, cur[1])
            new_key = self._priority(dist, transfers, node, line)
            if new_key < old_key:
                self._best_state[node] = ((node, line), dist, transfers)
        for node, (st, dist, transfers) in self._best_state.items():
            if node == self.source:
                continue
            self.dist_to[node] = dist
            self._transfer_count[node] = transfers
        if self.source not in self.dist_to:
            self.dist_to[self.source] = 0
            self._transfer_count.setdefault(self.source, 0)
        self._final_state = {node: st for node, (st, d, t) in
                             [((n, v[0], v[1], v[2]) for n, v in self._best_state.items())]}

    def _set_result(self, node, dist, transfers, state):
        self.dist_to[node] = dist
        self._transfer_count[node] = transfers

    def has_path_to(self, dest):
        return dest in self.dist_to and not (dest != self.source
                                             and self.dist_to[dest] == float("inf"))

    def _chosen_state(self, dest):
        if dest == self.source:
            return self._state_key(dest, NO_LINE)
        entry = self._best_state.get(dest)
        if entry is None:
            return None
        return entry[0]

    def path_with_edges(self, dest):
        """Return (path_ids, edges) from source to dest, or ([], []) if unreachable."""
        state = self._chosen_state(dest)
        if state is None and dest != self.source:
            return [], []
        path_ids = []
        edges = []
        cur = state
        while cur is not None and cur in self._edge_to:
            edge = self._edge_to[cur]
            edges.append(edge)
            path_ids.append(cur[0])
            cur = self._prev_state.get(cur)
            if cur is not None and cur[0] == self.source and cur[1] == "":
                path_ids.append(self.source)
                cur = None
        if not path_ids:
            path_ids = [self.source]
        else:
            path_ids.append(self.source) if path_ids[-1] != self.source else None
        path_ids.reverse()
        edges.reverse()
        return path_ids, edges

    def get_transfer_count(self, dest):
        if dest == self.source:
            return 0
        return self._transfer_count.get(dest, None)

"""Beijing Subway fare rules and travel time estimation."""
import math

# Left-closed/right-open tiers with boundary values moving to the higher tier,
# i.e. fare applies on intervals (0,6], (6,12], (12,22], (22,32] km plus extension.
_TIERS = [(6000, 3), (12000, 4), (22000, 5), (32000, 6)]
EXTENDED_BASE_FARE = 6
EXTENDED_STEP_METERS = 20000

MINUTES_PER_KM = 1.5
MINUTES_PER_TRANSFER = 5


def Sum_money(distance_meters):
    """Integer fare in yuan for a distance in meters (ceiling for fractions)."""
    d = math.ceil(distance_meters)
    if d <= 0:
        return 3
    for limit, fare in _TIERS:
        if d <= limit:
            return fare
    over = d - _TIERS[-1][0]
    return EXTENDED_BASE_FARE + math.ceil(over / EXTENDED_STEP_METERS)


def calculate_estimated_time(distance_meters, transfer_count):
    """Estimated travel time in minutes, rounded to nearest integer."""
    minutes = distance_meters / 1000.0 * MINUTES_PER_KM + transfer_count * MINUTES_PER_TRANSFER
    return int(round(minutes))

"""Shortest path search (Dijkstra with priority queue) over the subway graph.

States are (station_number, current_line). Carrying the line in the state lets
us count transfers (line changes) and enforce a max-transfer limit. Modes:
  shortest_distance : minimize total distance (transfers as tie-break)
  least_transfer    : minimize transfer count (distance as tie-break)
  comprehensive     : minimize distance + 1000m penalty per transfer
"""

from models import MinPQ

TRANSFER_PENALTY = 1000  # meters added per transfer in comprehensive mode
INF = float("inf")
NO_LINE = None
START = ""  # sentinel line name for the start state


class ShortestPath:
    def __init__(self, graph, source, config=None):
        self.graph = graph
        self.source = source

        mode = "shortest_distance"
        max_transfers = None
        preferred_lines = []
        if config is not None:
            mode = getattr(config, "mode", None) or "shortest_distance"
            max_transfers = getattr(config, "max_transfers", None)
            preferred_lines = getattr(config, "preferred_lines", None) or []
        self.mode = mode
        self.max_transfers = max_transfers
        self.preferred_lines = list(preferred_lines)

        self.dist_to = {}
        self._transfers = {}
        self._edge_to = {}     # state -> Edge that entered this state
        self._prev = {}        # state -> previous state
        self._best_state = {}  # station -> chosen (station, line) state
        self._run()

    def _key(self, node, line):
        return (node, line if line is not NO_LINE else START)

    def _rank(self, dist, transfers, line):
        """Comparison tuple for a candidate arrival; lower is better."""
        if self.mode == "least_transfer":
            primary, secondary = transfers, dist
        elif self.mode == "comprehensive":
            primary, secondary = dist + TRANSFER_PENALTY * transfers, transfers
        else:
            primary, secondary = dist, transfers
        pref = 0 if (line is not NO_LINE and line in self.preferred_lines) else 1
        return (primary, pref, secondary, dist, transfers)

    def _better(self, a, b):
        return a < b

    def _run(self):
        pq = MinPQ()
        start = self._key(self.source, NO_LINE)
        best_rank = {start: self._rank(0, 0, NO_LINE)}
        best_val = {start: (0, 0)}
        pq.insert(start, best_rank[start])

        while not pq.is_empty():
            state = pq.del_min()
            node = state[0]
            dist, transfers = best_val[state]
            for edge in self.graph.adj(node):
                line = edge.line
                prev_line = state[1]
                if prev_line == START:
                    ntransfers = transfers
                elif line == prev_line:
                    ntransfers = transfers
                else:
                    ntransfers = transfers + 1
                if self.max_transfers is not None and ntransfers > self.max_transfers:
                    continue
                ndist = dist + edge.weight
                nstate = self._key(edge.dest, line)
                nrank = self._rank(ndist, ntransfers, line)
                cur_rank = best_rank.get(nstate)
                if cur_rank is None or nrank < cur_rank:
                    best_rank[nstate] = nrank
                    best_val[nstate] = (ndist, ntransfers)
                    self._edge_to[nstate] = edge
                    self._prev[nstate] = state
                    pq.insert(nstate, nrank)

        # Per station choose the winning arrival state.
        self._source_dist = 0
        self._source_transfers = 0
        for state, (dist, transfers) in best_val.items():
            node = state[0]
            if node == self.source:
                continue
            cur = self._best_state.get(node)
            if cur is None or self._rank(dist, transfers, state[1]) < self._rank(
                    best_val[cur][0], best_val[cur][1], cur[1]):
                self._best_state[node] = state

    def _settle(self, node, dist, transfers):
        self.dist_to[node] = dist
        self._transfers[node] = transfers

    # public API -------------------------------------------------------------

    def has_path_to(self, dest):
        if dest == self.source:
            return True
        return dest in self._best_state

    def path_with_edges(self, dest):
        """Return (path_ids, edges): station numbers source..dest and edges used."""
        if dest == self.source:
            return [self.source], []
        state = self._best_state.get(dest)
        if state is None:
            return [], []
        path_ids = []
        edges = []
        cur = state
        while cur != self._key(self.source, NO_LINE):
            edges.append(self._edge_to[cur])
            path_ids.append(cur[0])
            cur = self._prev[cur]
        path_ids.append(self.source)
        path_ids.reverse()
        edges.reverse()
        return path_ids, edges

    def get_transfer_count(self, dest):
        if dest == self.source:
            return 0
        state = self._best_state.get(dest)
        if state is None:
            return None
        return best_val_transfer(self) if False else self._transfers.get(state, 0)


def best_val_transfer(sp):
    return sp._transfers.get(sp._best_state.get(sp.source), 0)

