def save_subway_data(data, path=DATA_FILE_PATH):
    """Write the network data back to JSON (for update workflows)."""
    with open(path, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)


def add_station(data, name, lines):
    """Add a station to the dataset if the name is not taken."""
    if any(s["name"] == name for s in data["stations"]):
        return False
    data["stations"].append({"name": name, "lines": list(lines)})
    return True


def add_connection(data, source, dest, distance, line):
    """Add a directed-listed connection (the graph treats it as undirected)."""
    data["connections"].append({"source": source, "dest": dest,
                                "distance": distance, "line": line})
    return True


def update_connection_distance(data, source, dest, line, distance):
    """Update the distance of an existing connection; False if not found."""
    for conn in data["connections"]:
        if {conn["source"], conn["dest"]} == {source, dest} and conn["line"] == line:
            conn["distance"] = distance
            return True
    return False


